// كتاب الصلاة — القسم الأول (أ): ص5–128 (أُعيدت قراءته من الصور)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب بدء الأذان (ص5–10)`,
    items: [
      { q: `أصل معنى «الصلاة» في اللغة`, p: `5–6`,
        n: `اختلف العلماء في أصل الصلاة: فقيل: هي الدعاء لاشتمالها عليه، وهذا قول جماهير أهل العربية والفقهاء وغيرهم. وقيل: لأنها ثانية لشهادة التوحيد كالمصلي من السابق في خيل الحلبة. وقيل: هي من (الصلوين) وهما عرقان مع الردف. وقيل: هما عظمان ينحنيان في الركوع والسجود، قالوا: ولهذا كُتبت (الصلاة) بالواو في المصحف. وقيل: هي من الرحمة. وقيل: أصلها الإقبال على الشيء، وقيل غير ذلك.`,
        o: NO_O,
        s: `أرجح الأقوال الأول والذي هو الدعاء لأنها مشتملة على الدعاء.`,
        f: [`(ص5) الأذان شرف الأمة الإسلامية، فمن شرفها وكرمها وكرامتها عند الله أمر الأذان، فالأذان نعمة من أجل النعم.`, `(ص6) «ناقوس»: أي جرس على الشكل المعروف والصوت المعروف.`] },
      { q: `حكم المشاورة: هل هي واجبة على النبي ﷺ؟ وهل يلزم الإمام الأخذ برأي المستشارين؟`, p: `6–7`,
        n: `وفيه التشاور في الأمور لا سيما المهمة؛ وذلك مستحب في حق الأمة بإجماع العلماء، واختلف أصحابنا هل كانت المشاورة واجبة على رسول الله ﷺ أم كانت سنة في حقه كما في حقنا؟ والصحيح عندهم وجوبها، وهو المختار، قال الله تعالى: ﴿وَشَاوِرْهُمْ فِي الأَمْرِ﴾ والمختار الذي عليه جمهور الفقهاء ومحققو أهل الأصول أن الأمر للوجوب. وفيه أنه ينبغي للمتشاورين أن يقول كل منهم ما عنده، ثم صاحب الأمر يفعل ما ظهرت له مصلحة.`,
        o: `نقل القرطبي اتفاق العلماء على أن المشاورة مستحبة في حق الأمة؛ واختلف الشافعية في وجوبها على النبي ﷺ: واجبة (الصحيح عندهم)، أو سنة في حقه كما في حقنا.`,
        s: `مسألة نقله اتفاق العلماء على أنه مستحب في حق الأمة فيه نظر، فقد ذكر القرطبي ... عن ابن عطية: «والشورى من قواعد الشريعة وعزائم الأحكام؛ من لا يستشير أهل العلم والدين فعزله واجب. هذا ما لا خلاف فيه»، وليس هذا بترك للمشاورة، فقد قال تعالى في صفات المؤمنين (وأمرهم شورى بينهم) وهذا دليل على الوجوب لأنه ذكرها صفة مستقرة لهم وإذا كان الأمر واجباً على النبي ﷺ فإنه واجب على من قام مقامه، فالإمام عليه أن يشاور الناس فيما ينزل بهم من أمور عظيمة، أما الأمور الخاصة بأن يشاور الإنسان غيره في شأنه الخاص مثلاً أو في شؤونه المهمة فهذا يمكن حمل الاستحباب عليه، ويمكن حمل هذا الإجماع على ما كان في الأمور خاصة وليس في أمر الإمام. وهناك فرق بين المشاورة وبين الأخذ برأي المستشارين: فالمشاورة أمر واجب على الصحيح بالنسبة للإمام، وأما أن يلتزم برأي من أشار عليه فلا يلزمه إلا أن يجمعوا على أمر لأن الأمة لا تجتمع على ضلالة؛ فإذا أجمع أهل علم محلة الإمام على أمر وخالف فيه واحد فقط أو حتى اثنان فالصحيح أنه يلزم الإمام الأخذ برأي المجموع، لقوله ﷺ: «لا يزال طائفة من أمتي ظاهرين على أمر الله وهم ظاهرون» (البخاري) وكلمة (طائفة) فلابد أن تكون جماعة وأقلها ثلاثة، والواحد والاثنان لا يقدحان في الإجماع. أما إذا اختلفوا فلا يلزمه رأي الأكثرية طالما كان الإمام مجتهداً، ويمكن الترجيح بالأكثرية في غياب الإمام أو في غياب اجتهاده، لأن عمر ﵁ أمر إذا اختلف أصحاب الشورى بأن اختار أربعة واحداً واختار اثنان واحداً أن يأخذوا برأي الأربعة، وأنه إذا استووا يكون رأي ابن عمر مرجحاً، فإذا لم توجد أنواع أخرى من الترجيح كما ذكرنا فلا يلزمه اجتهاد غيره إذا كان الإمام مجتهداً، وإذا فقد الإمام أو فقد اجتهاده أي لم يكن مجتهداً فوارد أن يكون مشروع زراعي أو صناعي أو مسألة تجارية وليس للإمام خبرة في هذا الباب ولابد أن يأخذ قرار فيكون أهل الخبرة في هذا الباب يكون رأيهم ملزماً له ويرجح بالأكثرية.`,
        f: [] },
      { q: `هل كان النبي ﷺ يجتهد؟ وهل شُرع الأذان بوحي أم باجتهاد؟ وحكم العمل بالرؤيا (المنام)`, p: `8`,
        n: `قال القاضي عياض رحمه الله: ظاهره أنه إعلام ليس على صفة الأذان الشرعي، بل إخبار بحضور الصلاة ووقتها. وهذا الذي قاله محتمل أو متعيّن، فقد صحّ في حديث عبد الله بن زيد في سنن أبي داود والترمذي وغيرهما أنه رأى الأذان في المنام فجاء إلى رسول الله ﷺ يُخبره به، فجاء عمر ﵁ فقال: يا رسول الله والذي بعثك بالحق لقد رأيت مثل الذي رأى. فهذا ظاهره أنه كان في مجلس آخر، فيكون الواقع الإعلام أولًا، ثم رأى عبد الله بن زيد، فشرعه النبي ﷺ بعد ذلك إما بوحي، وإما باجتهاده ﷺ على مذهب الجمهور في جواز الاجتهاد له، وليس هو عملًا بمجرد المنام. هذا ما لا يُشكّ فيه بلا خلاف.`,
        o: `مذهب الجمهور جواز الاجتهاد للنبي ﷺ.`,
        s: `الصحيح أن النبي ﷺ كان يجتهد ويقره الوحي، وإذا لم يقره نزل الوحي ببيان ما حصل فيه خطأ، فإذا نظرنا إلى خلاصة المسألة الآن وجدنا أنه لا فرق بين القولين أن هذا كان بوحي أو باجتهاد لأنه هو اجتهاد أقره الوحي فيكون وحياً. وهذا هو الصحيح لأن المنام إنما يُعمل به إذا أقره الوحي، وأما العمل بالمنام المجرد فلا، وهذا هو الفرق بين أهل السنة وبين طوائف من الصوفية الذين يجعلون المنامات حجة قطعية أو مرجحة بمجرده مستقلة بذاتها، وكذا الكشف والإلهام؛ فنحن نثبت أثر المنام ونثبت الاستئناس به ولكن لابد وأن يوافق الشرع، فيستأنس به في الترجيح وكذا الاستنباط، ولكن لا يستدل به استدلالاً مستقلاً لأنه قابل للخطأ والصواب في حق غير الأنبياء، فالمنام قابل أن يكون رؤية من الله وقابل أن يكون حُلم من الشيطان وقابل أن يكون حديث نفس وقابل أن يخطأ ويصيب الإنسان في التأويل لأن بعض المنامات يحتاج إلى تأويل وبعضها يكون على ظاهره.`,
        f: [] },
      { q: `القيام في الأذان: هل هو واجب أو شرط؟ وحكم أذان القاعد والمضطجع`, p: `8–9`,
        n: `(يا بلال قم فناد بالصلاة) قال القاضي عياض رحمه الله: فيه حجة لشرع الأذان من قيام، وأنه لا يجوز الأذان قاعدًا. قال: وهو مذهب العلماء كافة إلا أبا ثور فإنه جوّزه ووافقه أبو الفرج المالكي، وهذا الذي قاله ضعيف لوجهين: أحدهما أنا قدمنا عنه أن المراد بهذا النداء الإعلام بالصلاة لا الأذان المعروف. والثاني أن المراد قم فاذهب إلى موضع بارز فناد بالصلاة ليسمعك الناس من البعد، وليس فيه تعرض للقيام في حال الأذان، لكن يُحتج للقيام في الأذان بأحاديث معروفة غير هذا. وأما قوله: مذهب العلماء كافة أن القيام واجب فليس كما قال، بل مذهبنا المشهور أنه سنة، فلو أذّن قاعدًا بغير عذر صح أذانه لكن فاتته الفضيلة، وكذا لو أذّن مضطجعًا مع قدرته على القيام صح أذانه على الأصح لأن المراد الإعلام وقد حصل، ولم يثبت في اشتراط القيام شيء.`,
        o: `القاضي عياض: القيام واجب وهو مذهب العلماء كافة إلا أبا ثور وأبا الفرج المالكي. والنووي: سنة، ويصح الأذان قاعدًا ومضطجعًا.`,
        s: `الصحيح أن نقول بوجوب القيام لظاهر حديث وقوله (قم) أي اذهب إلى موضع بارز متضمن القيام، ونادِ بالصلاة أي وأنت قائم باستصحاب حال القيام السابق، ولكن لا يبطل الأذان من قعود، فنقول بالوجوب وعدم الشرطية. وهذا هو الأصل فظاهر الأمر الوجوب (قم يا بلال) فهذا دليل على وجوب الأذان قائماً.`,
        f: [] },
      { q: `إذا اجتمع من يتبرع بالأذان ومن يطلب أجرًا وهو أحسن صوتًا: أيهما يُقدَّم؟ (وحكم أخذ الأجرة على الأذان)`, p: `9–10`,
        n: `فيؤخذ منه: استحباب كون المؤذن رفيع الصوت وحسنه. وهذا متفق عليه. قال أصحابنا: فلو وجدنا مؤذنًا حسن الصوت يُطلَب على أذانه رزقًا وآخر يتبرع بالأذان لكنه غير حسن الصوت، فأيهما يؤخذ؟ فيه وجهان: أصحهما يرزق حسن الصوت، وهو قول ابن شريح. وذكر العلماء في حكمة الأذان أربعة أشياء: إظهار شعار الإسلام، وكلمة التوحيد، والإعلام بدخول وقت الصلاة وبمكانها، والدعاء إلى الجماعة.`,
        o: `وجهان عند الشافعية: يُرزق حسن الصوت (الأصح، وهو قول ابن سريج)، أو يُقدَّم المتبرع.`,
        s: `يُعطاه من بيت المال؛ والوجه الثاني الذي جعله مقابل للأصح أنه يكره أخذ الأجرة على الأذان وبالتالي فدرء المفاسد مقدم على جلب المصالح ففيه احتمال، فهو يرجح وهو المذهب عندهم ترجيح حسن الصوت مراعاةً لفضيلة حسن الصوت في هذا المقام.`,
        f: [`(ص9) وهذا دليل على أن الإنسان عليه ألا ينازع حسن الصوت الأذان، فربما يأتي إنسان ويريد أن يؤذن وهو ليس حسن الصوت ولا برفيع الصوت، فينبغي أن يترك حسن الصوت إذا وجد أن يؤذن، فهذا شعار لنا جميعاً فثواب للمجموع أكثر أن يؤذن حسن الصوت.`, `(ص10) والظاهر والله أعلم وجوب الأذان كما سنذكره إن شاء الله.`] },
    ],
  },
  {
    title: `باب الأمر بشفع الأذان وإيتار الإقامة (ص10–14)`,
    items: [
      { q: `قول الصحابي «أُمر بلال» و«أُمرنا» و«نُهينا»: هل هو مرفوع؟`, p: `11`,
        n: `(أُمر بلال) هو بضم الهمزة وكسر الميم؛ أي أمره رسول الله ﷺ، هذا هو الصواب الذي عليه جمهور العلماء من الفقهاء وأصحاب الأصول وجميع المحدثين، وشذ بعضهم فقال: هذا اللفظ وشبهه موقوف لاحتمال أن يكون الآمر غير رسول الله ﷺ، وهذا خطأ والصواب أنه مرفوع لأن إطلاق ذلك إنما ينصرف إلى صاحب الأمر والنهي وهو رسول الله ﷺ. ومثل هذا اللفظ قول الصحابي: أُمرنا بكذا، ونُهينا عن كذا، أو أُمر الناس بكذا، ونحوه فكله مرفوع سواء قال الصحابي ذلك في حياة رسول الله ﷺ أم بعد وفاته.`,
        o: `قول بعضهم (شاذ): هو موقوف لاحتمال أن يكون الآمر غير النبي ﷺ.`,
        s: `هذا الكلام صحيح على ما هو عليه ولكن نضيف إليه: [إلا أن تدل قرينة على أنه قصد أمر غير النبي ﷺ].`,
        f: [`(ص11) «هذا اللفظ وشبهه»: أي شبه لفظ أمر (أمرنا بكذا أو نهينا عن كذا).`] },
      { q: `الترجيع في الأذان: تعريفه وحكمه`, p: `12`,
        n: `واختلف العلماء في إثبات الترجيع كما سأذكره في الباب الآتي إن شاء الله تعالى.`,
        o: NO_O,
        s: `الترجيع وهو أن يكرر (أشهد أن لا إله إلا الله) مرتين و(أشهد أن محمد رسول الله) مرتين بصوت منخفض قبل أن يرفع صوته بها، اختلف في إثباته والصحيح التخيير.`,
        f: [] },
      { q: `عدد كلمات الإقامة وصفتها: مذاهب العلماء (الشافعي وأحمد، مالك، أبو حنيفة)`, p: `12–13`,
        n: `واختلف العلماء في لفظ (الإقامة): فالمشهور من مذهبنا الذي تظاهرت عليه نصوص الشافعي، وبه قال أحمد وجمهور العلماء أن الإقامة إحدى عشرة كلمة: [الله أكبر، الله أكبر، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، حي على الصلاة، حي على الفلاح، قد قامت الصلاة، قد قامت الصلاة، الله أكبر، الله أكبر، لا إله إلا الله]. وقال مالك رحمه الله في المشهور عنه: هي عشر كلمات فلم يثنِّ لفظ الإقامة، وهو قول قديم للشافعي. ولنا قول شاذ: أنه يقول في الأول: الله أكبر مرة، وفي الآخر الله أكبر، ويقول: قد قامت الصلاة مرة فتكون ثمان كلمات، والصواب الأول. وقال أبو حنيفة: الإقامة سبع عشرة كلمة فيثنيها كلها وهذا المذهب شاذ. قال الخطابي: مذهب جمهور العلماء والذي جرى به العمل في الحرمين والحجاز والشام واليمن ومصر والمغرب إلى أقصى بلاد الإسلام أن الإقامة فُرادى. قال الإمام أبو سليمان الخطابي رحمه الله تعالى: مذهب عامة العلماء أنه يكرر قوله (قد قامت الصلاة) إلا مالكًا فإن المشهور عنه أنه لا يكررها. والله أعلم.`,
        o: `مالك: عشر كلمات (لا تثنية لفظ «قد قامت الصلاة»)، وهو قول قديم للشافعي. أبو حنيفة: سبع عشرة كلمة فيثنيها كلها (وعدّه النووي شاذًّا). قول شاذ عند الشافعية: ثمان كلمات.`,
        s: `هذا غير ظاهر، فاعتبار شذوذ مذهب أبي حنيفة في هذه المسألة غير ظاهر، يمكن أن يرجح هو القول الثاني، بل الراجح صحة تسمية الإقامة بصحة الحديث بها في التمرين وغيره ولكنها تفعل أحياناً وتترك أحياناً والأغلب الأعم أن يفرد الإقامة (يوتر الإقامة) ولكن إذا ثناها يقول: (الله أكبر) أربعاً، أشهد أن لا إله إلا الله مرتين، و(أشهد أن محمد رسول الله) مرتين، (حي على الصلاة) مرتين، (حي على الفلاح) مرتين، (قد قامت الصلاة) مرتين، (الله أكبر الله أكبر) مرتين، لا إله إلا الله.`,
        f: [`(ص12) «أي غير معتبر ولذلك قال (والصواب الأول)»؛ وقد ذكرنا قبل ذلك أن اصطلاحات الإمام النووي والشافعية خصوصاً دقيقة جداً في ذكر درجات الخلاف: فكلمة الصواب التي يقابلها الباطل أو الشاذ فيكون الخلاف غير سائغ وغير معتبر لأنه خلاف النص والنص آتٍ في الحديث القادم بإثبات أن الإقامة يقال فيها (الله أكبر الله أكبر) إذاً معنى يوتر الإقامة إلا الإقامة وإلا الله أكبر في أوله وآخره فيقول الله أكبر مرتين في الأولى والثانية. ولفظ الصحيح يقابله الضعيف ولفظ الظاهر أو الراجح يقابله المرجوح. وأما لفظ الأصح فيقابله مقابل الأصح فيكون الخلاف فيها ضعيف جداً وقريب والترجيح فيه عسر ولكنه رجح بكلمة الأصح.`] },
      { q: `الحكمة في إفراد الإقامة وتثنية الأذان، وهل تكبير الإقامة (الله أكبر أولًا وآخرًا) يُعدّ تثنية؟`, p: `13`,
        n: `والحكمة في إفراد الإقامة وتثنية الأذان: أن الأذان لإعلام الغائبين، فيُكرَّر ليكون أبلغ في إعلامهم، والإقامة للحاضرين، فلا حاجة إلى تكرارها، ولهذا قال العلماء: يكون رفع الصوت في الإقامة دونه في الأذان، وإنما كرر لفظ الإقامة خاصة لأنه مقصود الإقامة. فإن قيل: قد قلتم إن المختار الذي عليه الجمهور أن الإقامة إحدى عشرة كلمة منها الله أكبر أولًا وآخرًا وهذا تثنية؟ فالجواب: أن هذا وإن كان صورة تثنية فهو بالنسبة إلى الأذان إفراد.`,
        o: NO_O,
        s: `هذا الكلام ينطبق على الأول لو اخترنا تربيع التكبير، لكن لا ينطبق على الثاني؛ لذلك قلنا أن الراجح في هذه المسألة الاحتياج إلى استثناء آخر بدليل منفصل، الحديث فيه استثناء متصل وهو قوله (إلا الإقامة)، ثم نخصص عموم قوله: (أمر أن يوتر الإقامة) نخصصه بدليل آخر وهو الحديث الآتي الذي ثنى فيه لفظ الله أكبر أولاً وآخراً، فيصبح عندنا تخصيص بدليل متصل (إلا الإقامة) وعندنا تخصيص بدليل منفصل وهو حديث أبي محذورة الآتي.`,
        f: [] },
      { q: `الإتيان بكل تكبيرتين بنفَس واحد في الأذان، وكيفية التربيع`, p: `14`,
        n: `ولهذا قال أصحابنا: يُستحب للمؤذن أن يقول كل تكبيرتين بنفَس واحد، فيقول في أول الأذان: [الله أكبر الله أكبر] بنفَس واحد، ثم يقول: [الله أكبر الله أكبر] بنفَس آخر. والله أعلم.`,
        o: NO_O,
        s: `خلافاً لمن يقول: (الله أكبر) بنفس ويقول (الله أكبر) بنفس آخر، فالسنة أن يقولها: (الله أكبر الله أكبر) بنفس واحد، ففي الحديث الآتي أن النبي ﷺ: [فَسَمِعَ رَجُلاً يَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. فَقَالَ رَسُولُ اللَّهِ ﷺ: «عَلَى الْفِطْرَةِ»]. وقوله ﷺ: (إِذَا قَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ أَحَدُكُمْ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ) فظاهر جداً أنه يقول ذلك بنفس واحد. وهذا اختيار منه لاستحباب التربيع وهو أن يقول (الله أكبر) أربع مرات، اثنين بنفس واحد واثنين بنفس؛ أما الترجيع بأن يقول الشهادتين الأربعة مرتين مرتين بصوت منخفض ومرة بصوت عالٍ.`,
        f: [`(ص14) الحمد لله الذي هدانا إلى سبيل الحق واجتبانا، فالإنسان إذا تدبر فضل الأذان إلى وسائل الإعلام الأخرى عند الأمم الأخرى التي يستوي فيها تنبيه البشر مع البهائم، فالذي يريد أن ينبه الغنم قد يصدر صوت بوق أو جرس أو نحو ذلك، ففضل الله ﷻ على أمة الإسلام بأن جعل الأذان الذي تضمن أشرف المعاني وأكمل معاني التوحيد والإيمان وما يحيي الإيمان في القلوب يتكرر بينهم بفضله ﷺ.`] },
    ],
  },
  {
    title: `باب صفة الأذان (ص15–18)`,
    items: [
      { q: `تربيع التكبير في أول الأذان أم تثنيته؟`, p: `16`,
        n: `هكذا وقع هذا الحديث في صحيح مسلم في أكثر الأصول في أوله [الله أكبر مرتين] فقط، ووقع في غير مسلم [الله أكبر الله أكبر الله أكبر الله أكبر] أربع مرات. قال القاضي عياض رحمه الله: ووقع في بعض طرق الفارسي في صحيح مسلم أربع مرات، وكذلك اختُلف في حديث عبد الله بن زيد في التثنية والتربيع، والمشهور فيه التربيع، وبالتربيع قال الشافعي وأبو حنيفة وأحمد وجمهور العلماء، وبالتثنية قال مالك واحتج بهذا الحديث وبأنه عمل أهل المدينة وهم أعرف بالسنن. واحتج الجمهور بأن الزيادة من الثقة مقبولة، وبالتربيع عمل أهل مكة وهي مجمع المسلمين في المواسم وغيرها ولم يُنكر ذلك أحد من الصحابة وغيرهم، والله أعلم.`,
        o: `مالك: التثنية (مرتين). الشافعي وأبو حنيفة وأحمد والجمهور: التربيع (أربع مرات).`,
        s: `والصحيح أن كلا الأمرين مشروع فيؤذن أحياناً بالتثنية ويؤذن أحياناً بالتربيع، فإن اجتماع المسلمين بمكة والمدينة حاصل ولا يُنكر هذا ولا يُنكر هذا، والصحيح أن هذا من باب الأفضلية والأفضلية أن يُربع لأنه يُزيد لأنه ذكر أكثر، أما جواز ذلك وأنه يفعل أحياناً فقد ثبت الحديث به، فإذا كان الأمر كذلك جاز أن يربع وجاز أن يثني، فيقول (الله أكبر) مرتين في الأول أو يقولها أربعة مرات.`,
        f: [] },
      { q: `الترجيع في الأذان: حكمه (ركن أم سنة أم تخيير)، ومذاهب العلماء فيه`, p: `17–18`,
        n: `وفي هذا الحديث: حجة بينة ودلالة واضحة لمذهب مالك والشافعي وأحمد وجمهور العلماء أن الترجيع في الأذان ثابت مشروع، وهو العود إلى الشهادتين مرتين مرتين برفع الصوت، بعد قولهما مرتين مرتين بخفض الصوت. وقال أبو حنيفة والكوفيون: لا يُشرع الترجيع عملًا بحديث عبد الله بن زيد فإنه ليس فيه ترجيع. وحجة الجمهور هذا الحديث الصحيح، والزيادة مقدَّمة مع أن حديث أبي محذورة هذا متأخر عن حديث عبد الله بن زيد، فإن حديث أبي محذورة سنة ثمان من الهجرة بعد حنين، وحديث ابن زيد في أول الأمر، وانضم إلى هذا كله عمل أهل مكة والمدينة وسائر الأمصار، وبالله التوفيق. واختلف أصحابنا في الترجيع هل هو ركن لا يصح الأذان إلا به، أم هو سنة ليس ركنًا حتى لو تركه صح الأذان مع فوات كمال الفضيلة؟ على وجهين: والأصح عندهم أنه سنة، وقد ذهب جماعة من المحدثين وغيرهم إلى التخيير بين فعل الترجيع وتركه، والصواب إثباته. والله أعلم.`,
        o: `أبو حنيفة والكوفيون: لا ترجيع. الجمهور (مالك والشافعي وأحمد): الترجيع مشروع؛ وعند الشافعية وجهان: ركن، أو سنة (الأصح). وجماعة من المحدثين وغيرهم: التخيير بين فعله وتركه.`,
        s: `الصحيح أن هذا أيضاً يفعل ويترك فيفعل هذا أحياناً ويتركه أحياناً لأنه ليس كل الروايات فيها الترجيع، وقد ثبت هذا وثبت هذا. كما قلنا الصحيح في الترجيع أن يفعل ويترك، والأفعال لا تتعارض حتى يلجأ إلى النسخ، لأن كلام النووي هذا مُشعر بأن حديث أبي محذورة متأخر فكأنه ناسخ، [والصحيح أن] حديث أبي محذورة متأخر والآخر صحيح مقدم لا تعارض بينهما بل كلاهما مشروع. وأنه سنة: وهذا هو الصحيح، لأنه قد ثبتت الروايات من غير ترجيع فدل ذلك على جواز ترك الترجيع. والصحيح هو التخيير ولكن مع فضيلة الترجيع لأنه ذكر لله أكثر.`,
        f: [`(ص18) «حيَّ على الصلاة»: بعض الناس في نطقهم لـ(حي) يكسرون الياء مع مدها وهذا خطأ والصحيح تشديد الياء وفتحها. و(حيعل) فعل مركب مؤلف.`] },
    ],
  },
  {
    title: `باب استحباب اتخاذ مؤذنين للمسجد الواحد (ص18–21)`,
    items: [
      { q: `جواز وصف الإنسان بعيبه للتعريف (الغيبة المباحة)`, p: `19`,
        n: `ومنها جواز وصف الإنسان بعيبٍ فيه للتعريف أو مصلحة تترتب عليه، لا على قصد التنقيص، وهذا أحد وجوه الغيبة المباحة وهي ستة مواضع يباح فيها ذكر الإنسان بعيبه ونقصه وما يكرهه، وقد بيّنتها بدلائلها واضحة في آخر كتاب الأذكار الذي لا يستغني عن مثله متدين، وسأذكرها إن شاء الله تعالى في كتاب النكاح عند قول النبي ﷺ: «أمّا معاوية فصعلوك» وفي حديث (إنّ أبا سفيان رجل شحيح) وفي حديث «بئس أخو العشيرة» وأنبّه على نظائرها في مواضعها إن شاء الله تعالى، وبالله التوفيق.`,
        o: NO_O,
        s: `فالعبرة في ذلك النية. والست مواضع هم: (الاستفتاء – التظلم – التعريف – الاستعانة على تغيير المنكر – النصيحة و(تحذير المسلمين من الشر) وتدخل فيها السادسة وهي المجاهر بفسقه وبدعته).`,
        f: [`(ص19) ابن أم مكتوم كان يدخل المعارك ليحفز المسلمين ويحثهم على القتال ﵁.`] },
      { q: `اتخاذ مؤذنين للمسجد الواحد وعددهم (حدّ الأربعة)`, p: `19–20`,
        n: `وفي هذا الحديث: استحباب اتخاذ مؤذنين للمسجد الواحد يُؤذَّن أحدهما قبل طلوع الفجر، والآخر عند طلوعه، كما كان بلال وابن أم مكتوم يفعلان. قال أصحابنا: فإذا احتيج إلى أكثر من مؤذنين اتُّخذ ثلاثة وأربعة فأكثر بحسب الحاجة، وقد اتخذ عثمان ﵁ أربعة للحاجة عند كثرة الناس. قال أصحابنا: ويُستحب أن لا يُزاد على أربعة إلا لحاجة ظاهرة.`,
        o: NO_O,
        s: `كل واحد منهم يؤذن في جهة. (لفعل الصحابة ﷺ.)`,
        f: [] },
      { q: `إذا تعدد المؤذنون: هل يؤذنون دفعة واحدة؟ ومن يتولى الإقامة (الراتب أم الأول)؟ وإقامة غير المؤذن`, p: `20`,
        n: `قال أصحابنا: وإذا ترتب للأذان اثنان فصاعدًا فالمستحب ألا يؤذنوا دفعة واحدة، بل إن اتسع الوقت ترتبوا فيه فإن تنازعوا في الابتداء به أقرع بينهم، وإن ضاق الوقت فإن كان المسجد كبيرًا أذنوا متفرقين في أقطاره، وإن كان ضيقًا وقفوا معًا وأذنوا، وهذا إذا لم يؤد اختلاف الأصوات إلى تهويش، فإن أدّى إلى ذلك لم يؤذن إلا واحد، فإن تنازعوا أقرع بينهم. وأما الإقامة فإن أذنوا على الترتيب فالأول أحق بها إن كان هو المؤذن الراتب، أو لم يكن هناك مؤذن راتب. فإن كان الأول غير المؤذن الراتب فأيهما أولى بالإقامة؟ فيه وجهان لأصحابنا أصحهما أن الراتب أولى لأنه منصبه، ولو أقام في هذه الصور غير من له ولاية الإقامة اعتد به على المذهب الصحيح المختار الذي عليه جمهور أصحابنا، وقال بعض أصحابنا: لا يُعتد به كما لو خطب بهم واحد وأم بهم غيره، فلا يجوز على قول. وأما إذا أذنوا معًا فإن اتفقوا على إقامة واحد وإلا فيقرع. قال أصحابنا رحمهم الله: ولا يقيم في المسجد الواحد إلا واحد إلا إذا لم تحصل الكفاية بواحد.`,
        o: `وجهان عند الشافعية فيمن يقيم إذا كان الأول غير الراتب: الراتب أولى (الأصح)، أو الأول. وقول لبعض الأصحاب: لا يُعتد بإقامة من ليس له ولاية الإقامة، وقيل غير ذلك.`,
        s: `وهذا ليس مستفاداً من الحديث، والذي يظهر والله أعلم أنهم إذا احتاجوا أذنوا في أقطار المسجد ونواحيه. ولذلك نقول الذي يقيم لصلاة الفجر هو الأول ولأن بلال ﷺ هو الذي كان يقيم للصلاة وبلال هو الذي كان يؤذن قبل الوقت. والراجح وهو الصحيح المختار أنه يجوز ولكن خلاف السنة، فالسنة أن الذي خطب هو من يؤم، والسنة أن الذي أذن هو الذي يقيم ولكن لو حدث غير ذلك صح. حتى لو الخطيب أقل حفظاً فهو الذي يصلي بهم. (كأن لا يسمع من هو بمؤخرة المسجد فالمؤذنين الآخرين يقيموا في مواضع أخرى ليسمعوا الناس إقامة الصلاة.)`,
        f: [] },
      { q: `الأذان والإقامة لجماعة ثانية تُقام في المسجد بعد الجماعة الأولى`, p: `21`,
        n: `وقال بعض أصحابنا: لا بأس أن يقيموا معًا إذا لم يؤدِّ إلى التهويش.`,
        o: NO_O,
        s: `ولذلك لا مانع إذا أقيمت جماعة ثانية في المسجد أن يؤذنوا ويقيموا كما فعل أنس ﷺ قال البخاري في صحيحه: [باب فضل صلاة الجماعة. وكان الأسود: " إذا فاتته الجماعة ذهب إلى مسجد آخر"، وجاء أنس بن مالك إلى مسجد قد صُلّي فيه فأذّن وأقام وصلى جماعة] وفي السنن الكبرى للبيهقي: عن يونس عن أبي عثمان، قال: " جاءنا أنس بن مالك وقد صلينا الفجر فأذّن وأقام ثم صلى الفجر بأصحابه " فالناس عندما يصلون جماعة ثانية يؤذنوا ويقيموا ولا يشوشوا على الناس بل على قدر أنفسهم.`,
        f: [] },
    ],
  },
  {
    title: `باب جواز أذان الأعمى إذا كان معه بصير (ص21)`,
    items: [
      { q: `أذان الأعمى، وكراهة أن يكون الأعمى مؤذنًا وحده`, p: `21`,
        n: `فيه حديث عائشة رضي الله عنها: (كان ابن أم مكتوم يؤذن لرسول الله ﷺ وهو أعمى) وقد تقدم معظم فقه الحديث في الباب قبله ومقصود الباب أن أذان الأعمى صحيح، وهو جائز بلا كراهة إذا كان معه بصير، كما كان بلال وابن أم مكتوم. قال أصحابنا: ويُكره أن يكون الأعمى مؤذنًا وحده. والله أعلم.`,
        o: NO_O,
        s: `(إذا كان معه بصير) بصير يخبره بالوقت لأنه إنما يعرف الأعمى الوقت بالخبر. (ويكره أن يكون مؤذنًا وحده) لأنه لن يستطيع معرفة الوقت على الدقة.`,
        f: [] },
    ],
  },
  {
    title: `باب الإمساك عن الإغارة على قوم في دار الكفر إذا سُمع فيهم الأذان (ص22–23)`,
    items: [
      { q: `الأذان للمنفرد: هل هو مشروع؟ وما حكمه؟`, p: `22`,
        n: `(فإذا هو راعي معزى) أُحتجّ به في أن الأذان مشروع للمنفرد، وهذا هو الصحيح المشهور في مذهبنا ومذهب غيرنا.`,
        o: NO_O,
        s: `ولكن الراجح أنه مستحب متأكد الاستحباب في حقه وليس بواجب، وإنما يؤذن وجوباً للجماعة فهو فرض كفاية لكل جماعة.`,
        f: [] },
      { q: `الأذان يمنع الإغارة على أهل الموضع: هل هو دليل على إسلامهم؟ وهل يُعدّ الدخول في المسجد إسلامًا؟`, p: `23`,
        n: `وفي الحديث دليل على أن الأذان يمنع الإغارة على أهل ذلك الموضع، فإنه دليل على إسلامهم.`,
        o: NO_O,
        s: `مع أنه قد يوجد فيهم كفار ولكنه إسلام بالقرينة لكل أهل المحلة. فالمؤذن نفسه لو رجع إلى الكفر لصار مرتداً، ولذلك نحن نفرق بين الأذان كقرينة للحكم بإسلام كل أهل البلد مثل المسجد قرينة لإسلام كل من فيه وقد يكون واحد نصراني دخل المسجد ليشاهد المسلمين وهم يصلون كالسياح إذا دخلوا بعض المساجد، فلا يلزم دخولهم المسجد إسلامهم بحيث أنه لو خرج وقال سأذهب إلى الكنيسة فهل يكون مرتداً؟ لا، بل دخوله المسجد ووجوده في طائفة تؤذن لا يُعد إسلاماً في حقه ولكن هي قرينة نكف بها عن الطائفة ككل وتعامل كطائفة مسلمة لجميع أفرادها ما لم يُعلم خلاف ذلك، بخلاف النطق المباشر فهذا إسلام حتى ولو معلوم عنه أنه كان كافراً قبل ذلك. فالشهادتان إسلام بمجردهما وهو إسلام للمؤذن نفسه بالقطع واليقين ولأهل المحلة بالقرينة، فإذا تبين أن واحداً من أهل المحلة كافر لا يصير مرتداً بسبب أن المؤذن قد أذن.`,
        f: [] },
      { q: `النطق بالشهادتين يكون إسلامًا وإن لم يكن باستدعاء، وخلاف «لا إله إلا الله» وحدها`, p: `23`,
        n: `وفيه أن النطق بالشهادتين يكون إسلامًا، وإن لم يكن باستدعاء ذلك منه، وهذا هو الصواب، وفيه خلاف سبق في أول كتاب الإيمان.`,
        o: `خلاف سبق في أول كتاب الإيمان (هل يشترط الاستدعاء للنطق؟، وهل يكفي النطق بـ«لا إله إلا الله» وحدها).`,
        s: `وهذا لا شك فيه أن نطق الشهادتين يكون إسلاماً ولا يحتاج إلى امتحانات ولا إلى تفصيل. الخلاف الذي ذكره: الصحيح فيه أنه ليس اختلاف وإنما هو اختلاف حال، وهو أن الوثني إذا نطق شهادة أن لا إله إلا الله فقط صار بذلك مسلماً، وأن الكتابي وكل من يقر بلا إله إلا الله لا يكون مسلماً حتى يضيف إلى ذلك أن محمداً رسول الله. فبعض العلماء ظن أن فيه قولان: أن لا إله إلا الله فقط تدخله في الإسلام من غير أن محمداً رسول الله، والصحيح أنه اختلاف حال وليس خلافاً حقيقياً؛ فحال الوثني غير حال الكتابي، ومن يقر بنبوة محمد ﷺ ومن يقر بالشهادتين ويكون كفره بغير جحد الشهادتين أو أحدهما فلا يكون إسلامه إسلاماً حتى يضيف إلى الشهادتين الإقرار بما كان سبباً في كفره. فهذا هو الصواب وأن الصحيح عدم وجود الخلاف في المسألة والخلاف فيه غير معتبر.`,
        f: [] },
    ],
  },
  {
    title: `باب استحباب القول مثل قول المؤذن لمن سمعه ثم يصلي على النبي ﷺ ثم يسأل الله له الوسيلة (ص24–33)`,
    items: [
      { q: `ما يقوله السامع عند الحيعلتين («حي على الصلاة» و«حي على الفلاح»)`, p: `27–28، 31`,
        n: `أما أحكام الباب: فيه استحباب قول سامع المؤذن مثل ما يقول إلا في الحيعلتين فإنه يقول: لا حول ولا قوة إلا بالله. وقوله ﷺ في حديث أبي سعيد: «إذا سمعتم النداء فقولوا مثل ما يقول المؤذن» عامٌّ مخصوصٌ بحديث عمر أنه يقول في الحيعلتين: لا حول ولا قوة إلا بالله. (وفي لفظ: قال القاضي عياض ... الحول والقوة.)`,
        o: `خلاف بعض العلماء القائلين في (حي على الصلاة وحي على الفلاح) يقول: [حي على الصلاة لا حول ولا قوة إلا بالله] فيقول حي على الصلاة لحديث أبي سعيد.`,
        s: `خلافاً لبعض العلماء القائلين في (حي على الصلاة وحي على الفلاح) يقول: [حي على الصلاة لا حول ولا قوة إلا بالله] فيقول حي على الصلاة لحديث أبي سعيد، وهذا غير ظاهر الصحيح كما قال النووي أنع عام مخصوص بحديث عمر ﷺ. الصحيح نص حديث عمر ﷺ أنه يردد ما بعد الشهادتين أيضاً ولا يكتفي بها بل يقول في (حي على الصلاة) و(حي على الفلاح) لا حول ولا قوة إلا بالله ويقول أيضاً: [اللهُ أَكْبَرُ اللهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللهُ].`,
        f: [`(ص27) «لا حول ولا قوة إلا بالله»: وكأن الحول هو البُعد عن الشر والقوة تكون في تحصيل الخير. («بمعنًى»: أي بمعنًى واحد.)`, `(ص28) وهذا يقوي ما قلناه في أن الحروف المقطعة في أوائل السور من أسماء الله تعالى [حرف من كل اسم].`] },
      { q: `حكم ترديد قول المؤذن: واجب أم مندوب؟`, p: `28، 30`,
        n: `وهل هذا القول مثل قول المؤذن واجب على من سمعه في غير الصلاة أم مندوب؟ فيه خلاف حكاه الطحاوي، الصحيح الذي عليه الجمهور أنه مندوب.`,
        o: `الجمهور: مندوب. الحنفية (حكاه الطحاوي): واجب على السامع.`,
        s: `مسألة استحباب ترديد قول المؤذن: قال الحنفية بالوجوب على السامع لأنه قال: [إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ] فقالوا بالوجوب ولا صارف لهذا الأمر، ولا يعرف جواباً للجمهور عليه يصرف هذا الأمر من الوجوب إلى الاستحباب. هناك خلاف في المسألة كما قلنا ولكن من جهة الدليل المجرد فلا نعرف صارفاً.`,
        f: [] },
      { q: `متى يردد السامع: بعد كل كلمة أم بعد فراغ المؤذن من الأذان؟ ومن يكون معذورًا (في الخلاء)`, p: `28–29`,
        n: `وفيه أنه يُستحب أن يقول السامع كل كلمة بعد فراغ المؤذن منها ولا ينتظر فراغه من كل الأذان. اعلم أنه يُستحب إجابة المؤذن بالقول مثل قوله لكل من سمعه من متطهر ومحدث وجنب وحائض وغيرهم ممن لا مانع له من الإجابة. فمن أسباب المنع: أن يكون في الخلاء، أو جماع أهله، أو نحوهما.`,
        o: NO_O,
        s: `يردد بعد كل كلمة، وقلنا أنه يقول: [الله أكبر الله أكبر] فصلها، يقولها على بعضها، وهذا الحديث من أصرح الأدلة على ذلك فمن الخطأ قول [الله أكبر] أربع مرات مقطعة لأن النبي ﷺ في الحديث قال: [إِذَا قَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. فَقَالَ أَحَدُكُمُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ] رغم أنهم جملتين إلا أنهم كالواحدة في القول. إلا أن يكون له عذر كأن يكون في صلاة أو في الخلاء فيؤجل ذكر الأذان حتى يزول عذره فيردد كل ما قاله المؤذن متتابعاً. والأظهر من الخلاء أن يكون أثناء قضاء الحاجة.`,
        f: [] },
      { q: `ما يقوله السامع بعد فراغ الأذان («وأنا أشهد...رضيت بالله ربًّا»)، وفضل الصلاة على النبي ﷺ والوسيلة`, p: `29`,
        n: `وفيه أنه يُستحب أن يقول بعد قوله: وأنا أشهد أن محمدًا رسول الله، رضيت بالله ربًّا، وبمحمد رسولًا، وبالإسلام دينًا. وفيه أنه يُستحب لمن رغّب غيره في خير أن يذكر له شيئًا من دلالته لينشّطه لقوله ﷺ: «فإنه من صلى عليّ مرة صلى الله عليه بها عشرًا ومن سأل لي الوسيلة حلت له الشفاعة». وفيه أن الأعمال يُشترط لها القصد والإخلاص لقوله ﷺ: (من قلبه).`,
        o: NO_O,
        s: `الصحيح أن [أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ ] التي في منتصف الأذان يرددها كما هي ولكن بعدما ينتهي من الأذان، يقول السامع: [وأنا أشهد أن لا إله إلا الله وحده لا شريك له وأن محمداً عبده ورسوله رضيت بالله رباً وبمحمد رسولاً وبالإسلام ديناً.] وهذا هو الصحيح الذي يُقال بعد فراغ المؤذن من الأذان.`,
        f: [`(ص29) «فإنه من صلى عليّ...»: وهو أسلوب الترغيب وهو أن يذكر له شيئاً من ثواب هذا الخير.`, `(ص29) «من قلبه»: فقد يقول الإنسان هذا الكلام وهو غافل وقد يقوله وهو ذاكر لقوله: (ثُمَّ قَالَ لاَ إِلَهَ إِلاَّ اللهُ. قَالَ لاَ إِلَهَ إِلاَّ اللهُ. مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ) وهذا دليل أن ليس كل الناس إذا تكلم بالأذان تستحضر معاني الأذان حين تتكلم به، فينبغي للعبد أن يستحضر معاني الأذان العظيمة التي هي قضايا الإيمان الكلية وهو يسمع الأذان ويردده وكذلك من يؤذن من باب أولى.`, `(ص31) هناك مناسبة لطيفة جداً في (رضيت بالله رباً) وهو شهود النعمة التي أنعم الله علينا بالإسلام وببعثة محمد ﷺ الجلية في الأذان فنعمة الله في الأذان جلية من المقارنة بين وسائل الإعلام عند الأمم الأخرى في الدعوة إلى العبادة فأولاً نعمة الله علينا بأن جعلنا نعبده وحده لا شريك له دون ما سواه، ثم بهذه النعمة العظيمة ببعثة النبي ﷺ وبهذا الدين العظيم، فتتجلى معاني الإسلام والإيمان في الأذان.`] },
      { q: `إجابة المؤذن وفي الصلاة: هل تُكره؟ وهل يحكي المصلي لفظ المؤذن في الفريضة والنافلة؟`, p: `29–30`,
        n: `ومنها أن يكون في صلاة فمن كان في صلاة فريضة أو نافلة فسمع المؤذن فلم يوافقه وهو في الصلاة، فإذا سلّم أتى بمثله. فلو فعله في الصلاة فهل يُكره؟ فيه قولان للشافعي ﷺ: أظهرهما أنه يكره لأنه إعراض عن الصلاة، لكن لا تبطل صلاته إن قال ما ذكرناه لأنها أذكار، فلو قال حي على الصلاة أو الصلاة خير من النوم بطلت صلاته إن كان عالمًا بتحريمه لأنه كلام آدمي. ولو سمع الأذان وهو في قراءة أو تسبيح أو نحوهما قطع ما هو فيه وأتى بمتابعة المؤذن. وقال القاضي عياض رحمه الله: اختلف أصحابنا هل يحكي المصلي لفظ المؤذن في صلاة الفريضة والنافلة، أم لا يحكيه فيهما، أم لا يحكيه في الفريضة دون النافلة؟ على ثلاثة أقوال، ومنعه أبو حنيفة فيهما.`,
        o: `ثلاثة أقوال عند المالكية: يحكيه في الفريضة والنافلة، أو لا يحكيه فيهما، أو يحكيه في النافلة دون الفريضة؛ ومنعه أبو حنيفة فيهما.`,
        s: `(يكره) ولأن النبي ﷺ ترك رد السلام الواجب حين سلم عليه: (فَقَالَ: " إِنَّ فِي الصَّلاَةِ لَشُغْلاً) ((خ) ١١٥٨ ، (م) ٣٤ – (٥٣٨)، (د) ٩٢٣). (حي على الصلاة) لأن كلمة (حي) كأنه يقول لإنسان (حي على الصلاة). (قطع ما هو فيه وأتى بمتابعة المؤذن) لأنه واجب الوقت أو سنة مؤكدة على الأقل. (وهذا قول الشافعية وهو الراجح) أي أن الإجابة تكره في الصلاة.`,
        f: [] },
      { q: `ما يقوله السامع عند الإقامة وعند «الصلاة خير من النوم» في أذان الفجر`, p: `30`,
        n: `ويتابعه في الإقامة كالأذان إلا أنه يقول في لفظ الإقامة: [أقامها الله، وأدامها]، وإذا ثوّب المؤذن في صلاة الصبح فقال: [الصلاة خير من النوم] قال سامعه: [صدقت، وبررت]. هذا تفصيل مذهبنا.`,
        o: NO_O,
        s: `وهذا لم يثبت فيه حديث صحيح فالصحيح أن يقول مثلما يقول، يقول: [قد قامت الصلاة، قد قامت الصلاة] طالما لم يرد دليل يخرج عن عموم قوله ﷺ: (إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ)، تركناها في (حي على الصلاة) و(حي على الفلاح) لحديث عمر ﷺ، وفي (الصلاة خير من النوم) يقول السامع (الصلاة خير من النوم). [صدقت وبررت] ليس عليه دليل.`,
        f: [] },
      { q: `إذا تعدد المؤذنون: هل يردد السامع مع كل مؤذن؟ وهل يتابع إلى آخر الأذان أم إلى آخر الشهادتين؟`, p: `31`,
        n: `قال: واختلفوا هل يقوله عند سماع كل مؤذن أم لأول مؤذن فقط. قال: واختلف قول مالك هل يتابع المؤذن في كل كلمات الأذان أم إلى آخر الشهادتين لأنه ذكر، وما بعده ليس بذكر، وبعضه تكرار لما سبق. والله أعلم.`,
        o: `مالك (اختلف قوله): هل يتابع في كل كلمات الأذان أم إلى آخر الشهادتين.`,
        s: `أي إذا كان هناك أكثر من مؤذن، فالأقرب والله أعلم أنه إن أمكنه أن يقوله مع كل مؤذن فليفعل، وإلا فإن عجز عن متابعة الجميع فاليكن مع أول مؤذن. الصحيح نص حديث عمر ﷺ أنه يردد ما بعد الشهادتين أيضاً ولا يكتفي بها بل يقول في (حي على الصلاة) و(حي على الفلاح) لا حول ولا قوة إلا بالله ويقول أيضاً: [اللهُ أَكْبَرُ اللهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللهُ].`,
        f: [] },
      { q: `الداخل إلى المسجد والمؤذن يؤذن للجمعة والإمام على المنبر: هل يصلي تحية المسجد أم يردد الأذان؟ (فتوى)`, p: `32`,
        n: NO_N,
        o: `فيه قولان: قول أنه يدرك تحية المسجد، والقول الثاني أن يردد الأذان أولًا.`,
        s: `إن دخل والمؤذن يؤذن للجمعة والإمام على المنبر فيه قولان: قول أنه يدرك تحية المسجد، والقول الثاني أن يردد الأذان أولاً، والذي عندي أن يردد الأذان أولاً؛ لأنه عندي هو أوجب. (فتوى)`,
        f: [`(ص32) في بيان المعاني العقدية للأذان عند القاضي عياض: «من الأمور التي دل عليها العقل بالإضافة إلى السمع وهي الأدلة النقلية وتتضمن الأمور التي دل عليها السمع من أدلة نقلية ولو لم تُعرف بالعقول المجردة، فالتوحيد دل عليه العقل والأدلة السمعية النقلية تؤكده. (أي دالة على العقائد العقلية والسمعية.) (بقوله: لا إله إلا الله.) وقوله «جائزة الوقوع» أي يقصد جائزة الوقوع عقلاً فإرسال الرسالة غير ممتنع عقلاً، بل الصحيح أن الرسالة من منة الله تعالى وأن العقول السليمة تشهد بأن الله أحق على نفسه أنه لا يعذب الناس إلا بعد إرسال الرسل. فالتوحيد من باب الواجبات والرسالة عند المتكلمين من باب الأفعال الجائزة.»`, `(ص33) لولا الإشارات الكلامية فإنها ليست من النفائس وللحق فإن الأذان أعظم مما ذكر، فعند التدبر نجد معاني التوحيد والإيمان أعظم مما ذكر.`] },
    ],
  },
  {
    title: `باب فضل الأذان وهرب الشيطان عند سماعه (ص33–38)`,
    items: [
      { q: `معنى «المؤذنون أطول الناس أعناقًا يوم القيامة»`, p: `35–36`,
        n: `فقوله ﷺ: (المؤذنون أطول الناس أعناقًا) هو بفتح همزة أعناقًا جمع عنق، واختلف السلف والخلف في معناه: فقيل: معناه أكثر الناس تشوفًا إلى رحمة الله تعالى لأن المتشوف يطيل عنقه إلى ما يتطلع إليه، فمعناه كثرة ما يرونه من الثواب. وقال النضر بن شميل: إذا ألجم الناس العرق يوم القيامة طالت أعناقهم لئلا ينالهم ذلك الكرب والعرق. وقيل: معناه أنهم سادة ورؤساء والعرب نصف السادة بطول العنق. وقيل: معناه أكثر أتباعًا. وقال ابن الأعرابي: معناه أكثر الناس أعمالًا. قال القاضي عياض وغيره: ورواه بعضهم (إعناقًا) بكسر الهمزة أي إسراعًا إلى الجنة، وهو من سير العنق.`,
        o: `أقوال: أكثر تشوفًا إلى رحمة الله؛ طول الأعناق حقيقةً يوم القيامة (النضر بن شميل)؛ السيادة؛ كثرة الأتباع؛ كثرة الأعمال (ابن الأعرابي)؛ (إعناقًا) أي إسراعًا إلى الجنة.`,
        s: `وهنا حمل الحديث على ظاهره وهذا أولى. (وقوله «إعناقًا»: أي السير السريع.)`,
        f: [] },
      { q: `شهادة الجن والإنس وغيرهم للمؤذن يوم القيامة: هل هي عامة للمؤمن والكافر والحيوان والجماد؟`, p: `36–37`,
        n: `قال العلماء: وإنما أدبر الشيطان عند الأذان لئلا يسمعه فيضطر إلى أن يشهد له بذلك يوم القيامة لقول النبي ﷺ: «لا يسمع صوت المؤذن جنٌّ ولا إنس ولا شيء إلا شهد له يوم القيامة». قال القاضي عياض: وقيل: إنما يشهد له المؤمنون من الجن والإنس، فأما الكافر فلا شهادة له. قال: ولا يُقبل هذا من قائله لما جاء في الآثار من خلافه. قال: وقيل: إن هذا فيمن يصح منه الشهادة ممن يسمع. وقيل: بل هو عام في الحيوان والجماد، وأن الله تعالى يخلق لها ولما لا يعقل من الحيوان إدراكًا للأذان وعقلًا ومعرفة. وقيل: إنما يُدبر الشيطان لعظم أمر الأذان لما اشتمل عليه من قواعد التوحيد، وإظهار شعائر الإسلام، وإعلانه. وقيل: ليأسه من وسوسة الإنسان عند الإعلان بالتوحيد.`,
        o: `أقوال: لا يشهد له إلا المؤمنون من الجن والإنس؛ أو فيمن تصح منه الشهادة؛ أو هو عام في الحيوان والجماد وأن الله يخلق لها إدراكًا وعقلًا ومعرفة؛ وفي سبب إدبار الشيطان: عظم أمر الأذان، أو اليأس من وسوسة الإنسان عند الإعلان بالتوحيد.`,
        s: `والإنس تشمل المؤمن والكافر. (وعن القول بالعموم في الحيوان والجماد:) وهذا هو الصحيح. (إدراكًا وعقلًا ومعرفة:) يكفي كلمة (إدراكًا) و(عقلًا) لا نعرفها.`,
        f: [] },
      { q: `الأفضل للإنسان: أن يرصد نفسه للأذان أم للإمامة؟`, p: `38`,
        n: `أما فقه الباب: فضيلة الأذان والمؤذن، وقد جاءت فيه أحاديث كثيرة في الصحيحين مصرِّحة بعظم فضله، واختلف أصحابنا هل الأفضل للإنسان أن يرصد نفسه للأذان أم للإمامة على أوجه: أصحها الأذان أفضل، وهو نص الشافعي في الأم وقول أكثر أصحابنا. والثاني الإمامة أفضل وهو نص الشافعي أيضًا. والثالث هما سواء. والرابع إن علم من نفسه القيام بحقوق الإمامة وجميع خصالها فهي أفضل، وإلا فالأذان، قاله أبو علي الطبري وأبو القاسم بن كج والمسعودي والقاضي حسين من أصحابنا.`,
        o: `أربعة أوجه عند الشافعية: الأذان أفضل (الأصح)، الإمامة أفضل، سواء، التفصيل (الإمامة أفضل إن علم القيام بحقوقها وإلا فالأذان).`,
        s: `الله أعلم، فليس عندنا دليل يرجح بين الأذان والإمامة في حق الناس، وأما في حق النبي ﷺ فلا شك أن الإمامة أفضل، وعلى أي الأحوال كان الأئمة من بعده يؤمون الناس: أبو بكر وعمر وعثمان وعلي ﷺ كانوا يؤمون الناس.`,
        f: [] },
      { q: `الجمع بين الإمامة والأذان لرجل واحد`, p: `38`,
        n: `وأما جمع الرجل بين الإمامة والأذان: فإن جماعة من أصحابنا يُستحب ألّا يفعله. وقال بعضهم: يُكره. وقال محققوهم وأكثرهم: أنه لا بأس به، بل يُستحب، وهذا أصح. والله أعلم.`,
        o: `قيل: يُستحب ألا يفعله، وقيل: يُكره، وقال أكثر المحققين: لا بأس به بل يُستحب (الأصح).`,
        s: `وهذا هو الظاهر ولا يُكره لعدم وجود دليل يدل على الكراهة. والأصح والأفضل أن يكون المؤذن غير الإمام ولكن إن فعل فصح ذلك ولا حرج.`,
        f: [] },
    ],
  },
  {
    title: `باب استحباب رفع اليدين حذو المنكبين مع تكبيرة الإحرام والركوع وفي الرفع من الركوع وأنه لا يفعله إذا رفع من السجود (ص39–49)`,
    items: [
      { q: `مواضع رفع اليدين في الصلاة: عند تكبيرة الإحرام وعند الركوع والرفع منه، وعند القيام من التشهد الأول، وفي السجود`, p: `40–42`,
        n: `أجمعت الأمة على استحباب رفع اليدين عند تكبيرة الإحرام، واختلفوا فيما سواها: فقال الشافعي وأحمد وجمهور العلماء من الصحابة ﵃ فمن بعدهم: يُستحب رفعهما أيضًا عند الركوع وعند الرفع منه، وهو رواية عن مالك. وللشافعي قول أنه يُستحب رفعهما في موضع آخر رابع وهو إذا قام من التشهد الأول، وهذا القول هو الصواب، فقد صح فيه حديث ابن عمر عن النبي ﷺ أنه كان يفعله، رواه البخاري، وصح أيضًا من حديث أبي حميد الساعدي، رواه أبو داود والترمذي بأسانيد صحيحة. وقال أبو بكر بن المنذر وأبو علي الطبري من أصحابنا وبعض أهل الحديث: يُستحب أيضًا في السجود. وقال أبو حنيفة وأصحابه وجماعة من أهل الكوفة: لا يُستحب في غير تكبيرة الإحرام، وهو أشهر الروايات عن مالك.`,
        o: `الجمهور (الشافعي وأحمد ومالك في رواية): عند الإحرام والركوع والرفع منه (وللشافعي قول بموضع رابع: القيام من التشهد الأول). ابن المنذر والطبري وبعض أهل الحديث: وفي السجود أيضًا. أبو حنيفة وأصحابه وجماعة من أهل الكوفة وأشهر الروايات عن مالك: لا يرفع إلا عند تكبيرة الإحرام.`,
        s: `استدلالاً بحديث مسلم: (أَنَّ أَبَا هُرَيْرَةَ كَانَ يُصَلِّي لَهُمْ فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ فَلَمَّا انْصَرَفَ قَالَ وَاللَّهِ إِنِّي لأَشْبَهُكُمْ صَلاَةً بِرَسُولِ اللَّهِ ﷺ.) وأكثر العلماء على تصحيح حديث (يكبر في كل خفض ورفع) وليس (يرفع في كل خفض ورفع) والألباني صحح حديث (يرفع في كل خفض ورفع) ويحمله على بعض الأحيان أي أنه يفعله أحياناً ولكن كثير من العلماء يرون هذه الرواية شاذة وهي مخالفة لما في الصحيحين في أنه لا يفعله في السجود، وذكر حديث ابن عمر في الصحيحين (ولا يفعل ذلك حين يسجد ولا حين يرفع رأسه من السجود). وهذا هو الأقرب عندي ولكن المسألة محل اجتهاد فلو فعل ذلك أحياناً لم ينكر عليه. وقول أبي حنيفة وهو قول مخالف للأحاديث الثابتة الصحيحة أن النبي ﷺ كان يرفع يديه إذا كبر في الركوع وفي الرفع منه.`,
        f: [`(ص40–41) تخريج الحديث: رواية البخاري عن ابن عمر: «إِذَا دَخَلَ فِي الصَّلاَةِ كَبَّرَ وَرَفَعَ يَدَيْهِ وَإِذَا رَكَعَ رَفَعَ يَدَيْهِ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَفَعَ يَدَيْهِ وَإِذَا قَامَ مِنَ الرَّكْعَتَيْنِ رَفَعَ يَدَيْهِ وَرَفَعَ ذَلِكَ ابْنُ عُمَرَ إِلَى نَبِيِّ اللَّهِ ﷺ»؛ ورواية أبي داود لحديث أبي حميد الساعدي في عشرة من أصحاب النبي ﷺ (ورفع اليدين في المواضع المذكورة)؛ ورواية الترمذي (حسن صحيح)، ورواية البخاري في التكبير والرفع أثناء القيام عن أبي هريرة.`] },
      { q: `حكم رفع اليدين في الصلاة: واجب أم مستحب؟`, p: `42`,
        n: `وأجمعوا على أنه لا يجب شيء من الرفع، وبهذا قال الإمام أبو الحسن أحمد بن سيَّار السيَّاري من أصحابنا أصحاب الوجوه، وقد حكيته عنه في شرح المهذب وفي تهذيب اللغات. وحُكي عن داود إيجابه عند تكبيرة الإحرام.`,
        o: `داود (حُكي عنه): يجب الرفع عند تكبيرة الإحرام.`,
        s: `هذا الإجماع هو الصارف لقول النبي ﷺ: (صلوا كما رأيتموني أصلي) مع ثبوت رفع اليدين في هذه المواضع فهذا الإجماع هو الصارف لهذا الحديث من الوجوب إلى الاستحباب. (أصحاب الوجوه:) أي علماء الشافعية المجتهدون في المذهب هم أصحاب الوجوه فيه. (وحُكي عن داود:) ولكن هذا خلاف شاذ.`,
        f: [] },
      { q: `صفة رفع اليدين: إلى أين ترتفع؟ ومحاذاة الكفين والإبهامين، وهل تُمدّ اليدان؟`, p: `43`,
        n: `وأما صفة الرفع: فالمشهور من مذهبنا ومذهب الجماهير أنه يرفع يديه حذو منكبيه بحيث تحاذي أطراف أصابعه فروع أذنيه أي أعلى أذنيه، وإبهاماه شحمتي أذنيه، وراحتاه منكبيه، فهذا معنى قولهم: حذو منكبيه، وبهذا جمع الشافعي ﷺ بين روايات الأحاديث فاستحسن الناس ذلك منه.`,
        o: `بعض العلماء يجعلها روايات متعارضة؛ وبعضهم يجعلها أحوالًا.`,
        s: `يحاذي بإبهاميه شحمتي الأذن ويحاذي براحة يديه منكبيه ولا يلزم اللمس فلم يرد اللمس، ولكن يحاذي بها ولو لمسها بدون قصد فلا شيء عليه ولكن هي المحاذاة فتكون أطراف الأصابع أمام أعلى الأذن وراحة يديه أمام المنكب لو نزل قليلاً فهذا من المسموح به؛ ومن الخطأ جعل أطراف الأصابع ممدودة إلى الأرض تجاه القبلة ولا يكاد يرفع يديه فهذا مما لم يرد نهائياً؛ فلم يرد اللمس ولم يرد الرفع القصير جداً. ولو أحد فعل ذلك سيحتج بفعل الشيخ فلان فلننتبه فقد سُئل الإمام أحمد فقيل له أنت تفعل كذا، فقال: أنا أسهو، فلا تحتج بالأفعال واحتج بالأقوال لأنه في بعض الأوقات لا يدري الإنسان فقد يكون مشغولاً بشيء فلم تتم الصفة كما ينبغي. ولا ينبغي أن يثني يديه فالسنة في رفع اليدين أن يمدها. ومحاذاة الكفين المنكبين ومن أين نستقبل القبلة وذلك من محاذاة المنكب: فالكف هو الراحة فلو حاذت المنكب فلو كان الكفين فاتجاه بعض فيكون بذلك عمودي على الكتف فلم تكون بذلك محاذية، ولكنه إذا حاذى براحتيه منكبيه فهذا يدل على استقبال القبلة. والبعض يجعلها أحوال وأحوال فيمكن أن يحاذي بها منكبيه فتكون يديه أمام المنكب فهذا حال، وأحياناً أخرى يرفع إلى أطراف أذنيه، وقول الشافعي حسن ولكن لا أقل من أنه يرفع يديه حذو منكبيه وجمع الشافعي أحسن لأنه يجمع بين الأدلة كلها وأقصى هبوط أن تكون اليد كلها أمام الكتف لكن السنة أن يرفع يديه إلى أطراف أذنيه.`,
        f: [] },
      { q: `وقت الرفع: هل يكون قبل التكبير أم معه أم بعده؟ وكيف يبتدئ وينتهي؟`, p: `43–44`,
        n: `وأما وقت الرفع: ففي الرواية الأولى [رفع يديه ثم كبّر]، وفي الثانية [كبّر ثم رفع يديه]، وفي الثالثة [إذا كبّر رفع يديه]، ولأصحابنا فيه أوجه: أحدها يرفع غير مكبِّر، ثم يبتدئ التكبير مع إرسال اليدين وينهيه مع انتهائه. والثاني يرفع غير مكبِّر، ثم يكبِّر ويداه قارَّتان، ثم يرسلهما. والثالث يبتدئ الرفع من ابتدائه التكبير، وينهيهما معًا. والرابع يبتدئ بهما معًا وينهي التكبير مع انتهاء الإرسال. والخامس وهو الأصح يبتدئ الرفع مع ابتداء التكبير، ولا استحباب في الانتهاء.`,
        o: `خمسة أوجه عند الشافعية في وقت الرفع بالنسبة للتكبير.`,
        s: `ثلاث روايات، والأقرب أنه إذا فعل أي من ذلك أجزأ. بل كل ذلك جائز، وكما قلنا الروايات تدل على جواز أن يرفع يديه ثم يكبر أو يكبر ثم يرفع يديه أو أن يكبر مع رفع اليدين، ويمكن أن يكون (ثم) لعطف فعل على فعل والله أعلم، ولكن الأقرب هو حمل الأحاديث على ظاهرها والتخيير بأن كل ذلك جائز. الفرق بين الثالث والرابع: في الرابع ينهي التكبير (الراء) مع انتهاء الارسال، وفي الثالث يبدأ في تنزيل يديه مع (الراء) فينزل يده قبل انتهاء التكبير وعندما يصل (للراء) في (أكبر) تكون يده على صدره مع انتهاء التكبير؛ والنووي يرجح أن يكون الرفع مع ابتداء التكبير ولا استحباب في الانتهاء أي كل ذلك هو فيه مخير، وهذا أولى من شغل النفس بهذا، فالنبي ﷺ كان يصنع هذا وهذا فالأمر واسع.`,
        f: [] },
      { q: `من فرغ من التكبير قبل تمام الرفع أو بالعكس، ومن قُطعت يداه أو إحداهما، ومن لم يقدر على الرفع إلا بزيادة أو نقص`, p: `44`,
        n: `(مسائل) فإن فرغ من التكبير قبل تمام الرفع أو بالعكس تمّم الباقي، وإن فرغ منهما حطَّ يديه ولم يستدم الرفع. ولو كان أقطع اليدين من المعصم أو إحداهما رفع الساعد، وإن قُطع من الساعد رفع العضد على الأصح، وقيل: لا يرفعه، ولو لم يقدر على الرفع إلا بزيادة على المشروع أو نقص منه فعل الممكن، فإن أمكن فعل الزائد...`,
        o: `قيل: لا يرفع العضد إذا قُطع من الساعد (قول مرجوح عند الشافعية).`,
        s: `(على الأصح) لأن الرفع فيه رفع جزء من العضد ليصل إلى الرفع حذو الأذنين ولذلك قال على الأصح. (وقيل: لا يرفعه) طريقة الإمام النووي عندما ينقل مذهبهم بها [أنه] إذا قال (وقيل) يكون هذا قول ضعيف مرجوح عند الشافعية. (ولو لم يقدر على الرفع إلا بزيادة...) بمعنى أن يده بها وجع ولا يستطيع الرفع إلا مسافة صغيرة لا تصل إلى المنكبين يرفع أم لا؟ يرفع (فاتقوا الله ما استطعتم)، وكذلك هو يستطيع أن يرفع عالياً جداً ولكن لا يستطيع الرفع عند هذا الموضع المشروع فعليه أن يرفع عالياً.`,
        f: [] },
      { q: `هيئة الكفين والأصابع عند الرفع (استقبال القبلة، كشفهما، تفريق الأصابع)`, p: `45`,
        n: `ويُستحب أن يكون كفّاه إلى القبلة عند الرفع، وأن يكشفهما، وأن يفرِّق بين أصابعهما تفريقًا وسطًا.`,
        o: NO_O,
        s: `(أن يكشفهما) لأن الصحابة رأوا راحتي النبي ﷺ. (تفريقًا وسطًا) لا نعرف نصًّا في هذه الجزئية.`,
        f: [] },
      { q: `من ترك الرفع حتى أتى ببعض التكبير: هل يرفع في الباقي؟ ومن تركه حتى أتمّه`, p: `45`,
        n: `ولو ترك الرفع حتى أتى ببعض التكبير رفعهما في الباقي، فلو تركه حتى أتمّه لم يرفعهما بعده.`,
        o: NO_O,
        s: `بل الظاهر أن يرفعها لرواية ابن عمر قال: كان رسول الله ﷺ إذا قام للصلاة رفع يديه حتى تكونا حذو منكبيه ثم كبر فإذا أراد أن يركع فعل مثل ذلك وإذا رفع من الركوع فعل مثل ذلك ولا يفعله حين يرفع رأسه من السجود. وتحتمل أنه أثناء الرفع كبر. وهذا أولى أن يحرص على أن يكون جزء من التكبير مقارن لجزء من الرفع.`,
        f: [] },
      { q: `مدّ التكبير: كيف يكون؟ وهل يمدّه أو يخففه؟`, p: `45`,
        n: `ولا يقصِّر التكبير بحيث لا يُفهم، ولا يبالغ في مدِّه بالتمطيط، بل يأتي به مبيَّنًا. وهل يمدُّه أو يخفِّفه؟ فيه وجهان أصحهما يخفِّفه.`,
        o: `وجهان: يمده أو يخففه (الأصح التخفيف).`,
        s: `وهو مد (الله) لا يقصره بحيث لا يفهم ولا يبالغ في مده بالتمطيط بل يمد المد الطبيعي. أي يجعله مقصور أم أربع حركات، الصحيح أنه يخففه لأن هذا موضع ليس من مواضع المد، فيمد مد طبيعي فقط فلا يمد مداً مبالغ فيه وهذا أصح؛ ولكن بعض القراء يقول: هذا مد تعظيم والصحيح ما ذكرنا.`,
        f: [] },
      { q: `موضع وضع اليدين في الصلاة: على الصدر أم فوق السرة أم تحتها؟`, p: `45–46`,
        n: `وإذا وضع يديه: حطَّهما تحت صدره فوق سُرَّته، هذا مذهب الشافعي والأكثرين، وقال أبو حنيفة وبعض أصحاب الشافعي: تحت سرَّته. والأصح أنه إذا أرسلهما إرسالًا خفيفًا إلى تحت صدره فقط، ثم يضع اليمين على اليسار. وقيل: يرسلهما إرسالًا بليغًا ثم يستأنف رفعهما إلى تحت صدره.`,
        o: `الشافعي والأكثرون: تحت الصدر فوق السرة. أبو حنيفة وبعض الشافعية: تحت السرة. وقيل: يرسلهما إرسالًا بليغًا ثم يرفعهما.`,
        s: `والصحيح أنه يضعها على صدره فإنه لم يثبت فوق السرة ولا تحتها أحاديث وإنما ثبتت أحاديث أنه ﷺ كان يضعها على صدره في الصلاة، فأي موضع من الضلوع تجزئ طالما يده موضوعة على الضلوع.`,
        f: [`(ص45–46) أحاديث وضع اليدين على الصدر: حديث طاووس مرسلاً (رواه أبو داود في المراسيل)، قال الأرنؤوط: مرسل رجاله ثقات؛ وقال الألباني: صحيح. وحديث وائل بن حجر عند ابن خزيمة: «صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ﷺ وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى يَدِهِ الْيُسْرَى عَلَى صَدْرِهِ» قال الألباني: إسناده ضعيف لأن مؤملاً وهو ابن إسماعيل سيئ الحفظ لكن الحديث صحيح جاء من طرق أخرى بمعناه وفي الوضع على الصدر أحاديث تشهد له. وفي «معرفة السنن والآثار» للبيهقي عن علي في الآية ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾: وضع يده اليمنى على يده اليسرى على صدره. والذي روي عنه تحت السرة لم يثبت، تفرد بإسناده عبد الرحمن بن إسحاق الواسطي وهو متروك، وروي عن ابن عباس ثم عن سعيد بن جبير وأبي مجلز مثل قولنا.`, `(ص46) روايات تحت السرة: حديث علي «مِنَ السُّنَّةِ وَضْعُ الْكَفِّ عَلَى الْكَفِّ فِي الصَّلاَةِ تَحْتَ السُّرَّةِ» (د ٧٥٦، ضعفه الألباني)، و(حم ٨٧٥) إسناده ضعيف، وحديث أبي هريرة «أَخْذُ الأَكُفِّ عَلَى الأَكُفِّ فِي الصَّلاَةِ تَحْتَ السُّرَّةِ» (د ٧٥٨، ضعيف لضعف عبد الرحمن بن إسحاق الكوفي)، وما رُوي عن سعيد بن جبير «فوق السرة» (د ٧٥٧، ضعيف).`] },
      { q: `الحكمة في رفع اليدين في الصلاة`, p: `47`,
        n: `واختلفت عبارات العلماء في الحكمة في رفع اليدين: فقال الشافعي ﵁: فعلته إعظامًا لله تعالى واتباعًا لرسول الله ﷺ. وقال غيره: هو استكانة واستسلام وانقياد، وكان الأسير إذا غُلب مدَّ يديه علامة للاستسلام. وقيل: هو إشارة إلى استعظام ما دخل فيه. وقيل: إشارة إلى طرح أمور الدنيا والإقبال بكليَّته على الصلاة ومناجاة ربه سبحانه وتعالى كما تضمن ذلك قوله (الله أكبر)، فيطابق فعله قوله. وقيل: إشارة إلى دخوله في الصلاة وهذا الأخير مختص بالرفع لتكبيرة الإحرام. وقيل غير ذلك، وفي أكثرها نظر. والله أعلم.`,
        o: `أقوال: إعظام لله واتباع للرسول (الشافعي)، استكانة واستسلام وانقياد، استعظام ما دخل فيه، طرح الدنيا والإقبال على الصلاة، إشارة إلى الدخول في الصلاة (خاص بتكبيرة الإحرام).`,
        s: `كلام الشافعي أحسن كلام: [تعظيماً لله واتباعاً لرسول الله ﷺ]. وليس هذا متعارضاً مع كلام الشافعي بل هو تفصيل له فإن التعظيم يشمل الاستكانة والاستسلام والانقياد. وأما «طرح أمور الدنيا» فهذه ليست بظاهرها وهو أن يرمي الدنيا وراء ظهره، فهذه إشارات تشبه إشارات الصوفية.`,
        f: [] },
      { q: `حكم تكبيرة الإحرام: ركن أم واجب أم سنة؟ (والفرق بين الركن والواجب والسنة عند الحنابلة)`, p: `48`,
        n: `وتكبيرة الإحرام: واجبة عند مالك والثوري والشافعي وأبي حنيفة وأحمد والعلماء كافة من الصحابة والتابعين فمن بعدهم ﷺ. إلا ما حكاه القاضي عياض رحمه الله وجماعة عن ابن المسيب والحسن والزهري وقتادة والحكم والأوزاعي أنه سنة ليس بواجب، وأن الدخول في الصلاة يكفي فيه النية، ولا أظن هذا يصح عن هؤلاء الأعلام مع هذه الأحاديث الصحيحة مع حديث علي ﷺ أن رسول الله ﷺ قال: «مفتاح الصلاة الطهور وتحريمها التكبير وتحليلها التسليم».`,
        o: `ابن المسيب والحسن والزهري وقتادة والحكم والأوزاعي (على ما حكاه القاضي عياض): سنة، والنية تكفي في الدخول.`,
        s: `كلمة (واجبة) عند مالك والشافعي وأبي حنيفة مقصدهم ما يساوي الركن لأن ليس عندهم تقسيم إلى واجب وركن، والواجب والركن تقسيم موجود عند الإمام أحمد فقط مثلما يقسم في الحج إلى: أفعال ركن وأفعال واجبة وأفعال مستحبة فكذلك يفعل في الصلاة وهذا أحسن تقسيم وأحسن مذهب تجتمع فيه الأدلة كما سيأتي. فالكلام يقصد به هنا الركنية. والفرق بينهما: أن الواجب: إذا تركه جاهل صحة صلاته، وإذا تركه ساهٍ سجد للسهو، وإذا تركه متعمداً بطلت الصلاة عند أحمد؛ أما الركن: فلا تصح الصلاة إلا به من جاهل أو ناسي أو عامد، فإذا تركه فلابد أن يأتي به حتى تصح صلاته؛ فالفرق بين الركن والواجب موجود عند الإمام أحمد فقط، فإذا وجد شيء واجب عند غيرهم فهي ركن عندهم ولذلك عند بقية المذاهب يرون أنه إذا ثبت شيء يجبر بسجود السهو فيكون عندهم ليس بواجب بل سنة مؤكدة، فالتشهد الأوسط عند مالك والشافعي يرونه سنة مؤكدة لأنه يجبر بسجود السهو. التحريم تشبيهاً لها بالحج وهو أن هناك لحظة يدخل فيها في المناسك وكذلك هناك لحظة يدخل فيها للعبادة وهي التكبير، وتحليلها التسليم تشبيهاً لها بالتحلل من المناسك أيضاً. ونحن لا نشك في ركنية تكبيرة الإحرام لصحة ذلك في حديث المسيء صلاته وهو الأصل في معرفة الأركان.`,
        f: [] },
      { q: `لفظ التكبير: هل يجزئ غير «الله أكبر»؟ («الله الأكبر»، «الله الكبير»، «الرحمن أكبر»، «الله أعظم»)`, p: `48–49`,
        n: `ولفظة التكبير (الله أكبر)، فهذا يجزي بالإجماع. قال الشافعي: ويجزي [الله الأكبر] لا يجزي غيرهما، وقال مالك: لا يجزي إلا [الله أكبر]، وهو الذي ثبت أن النبي ﷺ كان يقوله، وهذا قول منقول عن الشافعي في القديم، وأجاز أبو يوسف (الله الكبير)، وأجاز أبو حنيفة الاقتصار فيه على كل لفظ فيه تعظيم الله تعالى كقوله الرحمن أكبر، أو الله أجل أو أعظم، وخالفه جمهور العلماء من السلف والخلف. والحكمة في ابتداء الصلاة بالتكبير افتتاحها بالتنزيه والتعظيم لله تعالى ونعته بصفات الكمال. والله أعلم.`,
        o: `الشافعي (الجديد): يجزئ «الله أكبر» و«الله الأكبر». مالك والشافعي في القديم وأحمد: لا يجزئ إلا «الله أكبر». أبو يوسف: «الله الكبير». أبو حنيفة: كل لفظ فيه تعظيم لله تعالى.`,
        s: `وهذا هو الصحيح أنه لا يجزئ إلا (الله أكبر) ولم يرد غير ذلك، والأصل في العبادة التوقيف، فكما لا يجوز أن نقول مثلاً "استجاب الله لمن شكره" بالمعنى فكذلك فلابد أن نلتزم بالألفاظ، إذ كان النبي ﷺ قد قال للذي قال: ورسولك الذي أرسلت، قال: لا، بل قل: "ونبيك الذي أرسلت" في غير الصلاة وقد أكد على التكبير، وكل من نقل صلاته ﷺ لم ينقل إلا (الله أكبر) فلم ينقلوا قط (الله الأكبر) ولا (الله الكبير) ولا (الله أعظم) مرة من المرات. فيكون كلام الشافعي القديم هو المعتمد وقول مالك وهو قول أحمد.`,
        f: [`(ص49) وكذلك تصغير كل شيء يهم العبد من أمور الدنيا حتى يقبل بصلاته على الله ﷻ. (تعليقًا على الحكمة في ابتداء الصلاة بالتكبير.)`] },
    ],
  },
  {
    title: `باب إثبات التكبير في كل خفض ورفع في الصلاة إلا رفعه من الركوع فيقول فيه سمع الله لمن حمده (ص49–55)`,
    items: [
      { q: `تكبيرات الانتقال في الصلاة: عددها، وحكمها (ركن أم واجب أم سنة)، ومن تلا آية سجدة`, p: `51–52`,
        n: `فيه إثبات التكبير في كل خفض ورفع إلا في رفعه من الركوع فإنه يقول: سمع الله لمن حمده، وهذا مُجمَع عليه اليوم ومن الأعصار المتقدمة، وقد كان فيه خلاف في زمن أبي هريرة، وكان بعضهم لا يرى التكبير إلا للإحرام، وبعضهم يزيد عليه بعض ما جاء في حديث أبي هريرة، وكان هؤلاء لم يبلغهم فعل رسول الله ﷺ، ولهذا كان أبو هريرة يقول: إني لأشبهكم صلاة برسول الله ﷺ، واستقر العمل على ما في حديث أبي هريرة هذا: ففي كل صلاة ثنائية إحدى عشرة تكبيرة: وهي تكبيرة الإحرام، وخمس في كل ركعة. وفي الثلاثية سبع عشرة: وهي تكبيرة الإحرام، وتكبيرة القيام من التشهد الأول، وخمس في كل ركعة. وفي الرباعية اثنتان وعشرون، ففي المكتوبات الخمس: أربع وتسعون تكبيرة. واعلم أن تكبيرة الإحرام واجبة، وما عداها سنة، لو تركه صحت صلاته، لكن فاتته الفضيلة، وموافقة السنة. هذا مذهب العلماء كافة إلا أحمد بن حنبل ﷺ وفي إحدى الروايتين عنه أن جميع التكبيرات واجبة، ودليل الجمهور أن النبي ﷺ علّم الأعرابي الصلاة فعلّمه واجباتها فذكر منها تكبيرة الإحرام ولم يذكر ما زاد، وهذا موضع البيان ووقته، ولا يجوز التأخير عنه.`,
        o: `الجمهور: تكبيرة الإحرام واجبة وما عداها سنة. أحمد (في إحدى الروايتين): جميع التكبيرات واجبة. (وكان بعضهم في زمن أبي هريرة لا يرى التكبير إلا للإحرام.)`,
        s: `قلنا أنه يقصد أنها ركن. فإنها [إحدى الروايتين] هي المرجحة، وهي أنها واجبة ولكن ليست واجبة كما عند الجمهور، فهي عنده واجبة وليست بركن. قلنا حديث المسيء صلاته ما من أحد من العلماء إلا وأوجب شيئاً زائداً على ما في حديث المسيء صلاته استدلالاً بالأحاديث الأخرى إلا الإمام أحمد رحمه الله فإن مذهبه أن حديث المسيء صلاته أصل في الأركان، وأفعال النبي ﷺ وأقواله أصل في بيان الواجبات بالإضافة إلى الأركان، وإذا وقع إجماع أو دل دليل على عدم وجوب شيء من هذه الأفعال والأقوال فهو الصارف إلى الاستحباب؛ وبهذا فإن أفعال الصلاة ثلاثة أنواع: فالواردة في حديث المسيء صلاته هي الأركان التي لابد من فعلها ولا يجوز تركها ولا تصح الصلاة إلا بها عمداً أو سهواً أو جهلاً. وما سوى ذلك من الأفعال التي ورد بها أمر مباشر من قول النبي ﷺ أو فعل مع قوله: (صلوا كما رأيتموني أصلي)، ولم يصرفها صارف من كتاب أو سنة أو إجماع إلى الاستحباب فهي واجبات، إذا سها عنها سجد للسهو وإذا تركها جاهلاً صحة صلاته حتى يُعلم، فتكون العلة في عدم بلاغ المسيء صلاته في هذا الموطن حتى لا تستكثر عليه فيعجز عن حفظها فعلمه النبي ﷺ ما تصح به صلاته فقط ويعفى عن باقي الواجبات لجهله، ولكن لا يجوز تركها عمداً، فإذا تركها عمداً بطلت صلاته عند أحمد.`,
        f: [`(ص51) فبعضهم كان يقول التكبير في بعض الأحيان ويترك الباقي، والذي يدل على وجود الخلاف أنهم قالوا له: (فَقُلْنَا يَا أَبَا هُرَيْرَةَ: مَا هَذَا التَّكْبِيرُ؟) لوجود أُناس كانت تصلي على خلاف ذلك.`, `(ص52) وسيزاد عليها لو أنه قرأ في آياتها سجدة فإنه يكبر في كل خفض ورفع على ظاهر الحديث أنه يكبر كلما خفض ورفع وهذا هو الصحيح خلافاً لبعض المعاصرين القائلين أن تكبير سجود التلاوة غير مشروع بل هو مشروع لأنه داخل في عموم قوله يكبر في كل خفض ورفع.`] },
    ],
  },
];
